t.script:
//
function tonerGoBack() {
    if (document.referrer) {
        window.location.href = document.referrer;
    } else {
        window.history.back();
    }
}

document.addEventListener("DOMContentLoaded", function () {
    const accordionCards = document.querySelectorAll(".toner-accordion-card");
    const expandAllButton = document.getElementById("tonerExpandAllButton");
    const tonerOptions = document.querySelectorAll(".toner-option");
    const tonerCheckboxes = document.querySelectorAll(".toner-checkbox");
    const validateButton = document.getElementById("tonerValidateButton");
    const submitButton = document.getElementById("tonerSubmitButton");
    const validationResult = document.getElementById("tonerValidationResult");
    const form = document.getElementById("tonerRequestForm");

    let allExpanded = false;
    let validationCompleted = false;

    accordionCards.forEach(function (card) {
        const trigger = card.querySelector(".toner-accordion-trigger");

        trigger.addEventListener("click", function () {
            card.classList.toggle("open");
            updateExpandAllButton();
        });
    });

    if (expandAllButton) {
        expandAllButton.addEventListener("click", function () {
            allExpanded = !allExpanded;

            accordionCards.forEach(function (card) {
                card.classList.toggle("open", allExpanded);
            });

            updateExpandAllButton();
        });
    }

    function updateExpandAllButton() {
        const openCards = document.querySelectorAll(
            ".toner-accordion-card.open"
        ).length;

        allExpanded = accordionCards.length > 0 &&
            openCards === accordionCards.length;

        if (!expandAllButton) {
            return;
        }

        if (allExpanded) {
            expandAllButton.innerHTML =
                '<i class="fa fa-compress"></i> Contraer todo';
        } else {
            expandAllButton.innerHTML =
                '<i class="fa fa-expand"></i> Expandir todo';
        }
    }

    tonerOptions.forEach(function (option) {
        const checkbox = option.querySelector('input[type="checkbox"]');

        checkbox.addEventListener("change", function () {
            option.classList.toggle("selected", checkbox.checked);
            validationCompleted = false;
            hideValidation();
        });
    });

    if (validateButton) {
        validateButton.addEventListener("click", function () {
            validateRequest();
        });
    }

    if (form) {
        form.addEventListener("submit", function (event) {
            const hasSelection = Array.from(tonerCheckboxes).some(function (item) {
                return item.checked;
            });

            if (!hasSelection) {
                event.preventDefault();
                showValidation(
                    "danger",
                    "Debe seleccionar al menos un tóner."
                );
                return;
            }

            submitButton.disabled = true;
            submitButton.innerHTML =
                '<i class="fa fa-spinner fa-spin"></i> Registrando...';
        });
    }

    function validateRequest() {
        const hasSelection = Array.from(tonerCheckboxes).some(function (item) {
            return item.checked;
        });

        if (!hasSelection) {
            showValidation(
                "danger",
                "Debe seleccionar al menos un tóner."
            );
            return;
        }

        validateButton.disabled = true;
        validateButton.innerHTML =
            '<i class="fa fa-spinner fa-spin"></i> Revisando...';

        const formData = new FormData();
        const equipmentInput = form.querySelector(
            'input[name="id_registro"]'
        );

        formData.append("equipment_id", equipmentInput.value);
        formData.append(
            "toner_black",
            document.getElementById("toner_black") &&
            document.getElementById("toner_black").checked
        );
        formData.append(
            "toner_cyan",
            document.getElementById("toner_cyan") &&
            document.getElementById("toner_cyan").checked
        );
        formData.append(
            "toner_magenta",
            document.getElementById("toner_magenta") &&
            document.getElementById("toner_magenta").checked
        );
        formData.append(
            "toner_yellow",
            document.getElementById("toner_yellow") &&
            document.getElementById("toner_yellow").checked
        );

        const counterBn = document.getElementById("contometro_black");
        const counterColor = document.getElementById("contometro_color");

        formData.append(
            "counter_bn",
            counterBn ? counterBn.value : 0
        );
        formData.append(
            "counter_color",
            counterColor ? counterColor.value : 0
        );

        fetch("/toner/validate_request_http", {
            method: "POST",
            body: formData
        })
        .then(function (response) {
            return response.json();
        })
        .then(function (data) {
            validationCompleted = true;

            if (!data.can_create) {
                showValidation(
                    "danger",
                    data.message || "La solicitud no puede registrarse."
                );
                return;
            }

            if (data.review_required || data.requires_evidence) {
                showValidation(
                    "warning",
                    data.message ||
                    "La solicitud puede registrarse, pero requiere revisión interna."
                );
            } else {
                showValidation(
                    "info",
                    data.message ||
                    "La solicitud puede registrarse para evaluación interna."
                );
            }
        })
        .catch(function (error) {
            console.error("Error validando solicitud:", error);

            showValidation(
                "danger",
                "No fue posible completar la revisión. Puede intentar nuevamente."
            );
        })
        .finally(function () {
            validateButton.disabled = false;
            validateButton.innerHTML =
                '<i class="fa fa-search"></i> Revisar solicitud';
        });
    }

    function showValidation(type, message) {
        validationResult.className =
            "toner-validation-result visible " + type;

        validationResult.innerHTML =
            '<i class="fa fa-info-circle"></i>' +
            "<div>" + message + "</div>";

        validationResult.scrollIntoView({
            behavior: "smooth",
            block: "center"
        });
    }

    function hideValidation() {
        validationResult.className = "toner-validation-result";
        validationResult.innerHTML = "";
    }
});
//

//
function tonerGoBackBlocked() {
    if (document.referrer) {
        window.location.href = document.referrer;
    } else {
        window.history.back();
    }
}
//

//
function tonerGoBackNoSelection() {
    if (document.referrer) {
        window.location.href = document.referrer;
    } else {
        window.history.back();
    }
}
//
